/** Traduit un texte français vers la locale (repli : le texte lui-même). */
export function t(text: string, locale?: string): string {
  if (!locale) return text;
  return D[text]?.[locale as Locale] ?? text;
}

const RTL = new Set(['ar', 'ur']);

export function isRtlLocale(locale?: string): boolean {
  return Boolean(locale && RTL.has(locale));
}
